95	extern "C" {
96	
97	// Real libc/libcrypto entry points provided by the --wrap linker mechanism.
98	int __real_open(const char* path, int flags, ...);
99	ssize_t __real_write(int fd, const void* buffer, size_t count);
100	int __real_fsync(int fd);
101	int __real_close(int fd);
102	int __real_RAND_bytes(unsigned char* buf, int num);
103	void __real_OPENSSL_cleanse(void* ptr, size_t len);
104	
105	namespace {
106	
107	constexpr std::size_t kKeyBytes = 32;
108	
109	// Descriptor currently known to belong to the key file under test, or -1.
110	int g_keyFd = -1;
111	
112	// Key buffer most recently handed to RAND_bytes, so the OPENSSL_cleanse
113	// wrapper can recognise (and log) its wipe.
114	unsigned char* g_randBuf = nullptr;
115	int g_randBufSize = 0;
116	
117	// Continuity bookkeeping for EF_TEST_WRITE_LOG.
118	unsigned char g_keySnapshot[kKeyBytes];
119	bool g_haveSnapshot = false;     // the snapshot below is valid
120	std::size_t g_progress = 0;      // bytes acknowledged so far (pre-call offset)
121	
122	bool envFlagSet(const char* name) {
123	    const char* value = std::getenv(name);
124	    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
125	}
126	
127	bool isKeyPath(const char* path) {
128	    const char* target = std::getenv("EF_TEST_TARGET");
129	    return target == nullptr || std::strcmp(path, target) == 0;
130	}
131	
132	bool isKeyFd(int fd) {
133	    return fd != -1 && fd == g_keyFd;
134	}
