136	// Preserve errno across the bookkeeping I/O so the injected failure code is
137	// what the product code actually observes.
138	class ErrnoSaver {
139	public:
140	    ErrnoSaver() : saved_(errno) {}
141	    ~ErrnoSaver() { errno = saved_; }
142	
143	private:
144	    int saved_;
145	};
