147	void logLine(const char* pathEnv, const char* mode, const char* text) {
148	    const char* logPath = std::getenv(pathEnv);
149	    if (logPath == nullptr || logPath[0] == '\0') {
150	        return;
151	    }
152	    ErrnoSaver saver;
153	    std::FILE* file = std::fopen(logPath, mode);
154	    if (file == nullptr) {
155	        return;
156	    }
157	    std::fputs(text, file);
158	    std::fputc('\n', file);
159	    std::fclose(file);
160	}
161	
162	void logKeyLine(const char* text) {
163	    logLine("EF_TEST_KEY_LOG", "a", text);
164	}
165	
166	void logVerifyHeader(const unsigned char* buffer) {
167	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
168	    char line[kPrefix + 2 * kKeyBytes + 1];
169	    char* out = line;
170	    std::strcpy(out, "VERIFY ");
171	    out += 7;
172	    static const char hex[] = "0123456789abcdef";
173	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
174	        *out++ = hex[buffer[i] >> 4];
175	        *out++ = hex[buffer[i] & 0x0f];
176	    }
177	    *out = '\0';
178	    logLine("EF_TEST_WRITE_LOG", "w", line);
179	}
180	
181	void logCall(std::size_t offset, std::size_t requested,
182	             ssize_t returned, int reportedErrno) {
183	    char line[128];
184	    if (returned < 0) {
185	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd %d",
186	                      offset, requested, returned, reportedErrno);
187	    } else {
188	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd",
189	                      offset, requested, returned);
190	    }
191	    logLine("EF_TEST_WRITE_LOG", "a", line);
192	}
193	
194	void logVerifyFailed(const char* reason) {
195	    char line[160];
196	    std::snprintf(line, sizeof(line), "VERIFY-FAILED %s", reason);
197	    logLine("EF_TEST_WRITE_LOG", "a", line);
198	}
