200	// On the first key-file write, snapshot the key; afterwards confirm that the
201	// caller resumes exactly at the acknowledged offset and presents the matching
202	// slice of the same key. Any mismatch is a product-code defect: abort so the
203	// regression run can never pass on a silently regenerated/garbled key.
204	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
205	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
206	        return;
207	    }
208	    const auto* bytes = static_cast<const unsigned char*>(buffer);
209	    if (!g_haveSnapshot) {
210	        if (count != kKeyBytes) {
211	            logVerifyFailed("first write did not carry the whole 32-byte key");
212	            std::abort();
213	        }
214	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
215	        g_haveSnapshot = true;
216	        logVerifyHeader(g_keySnapshot);
217	        return;
218	    }
219	    if (g_progress > kKeyBytes) {
220	        logVerifyFailed("offset past end of key");
221	        std::abort();
222	    }
223	    const std::size_t remaining = kKeyBytes - g_progress;
224	    if (count != remaining) {
225	        logVerifyFailed("write length does not match the bytes still pending");
226	        std::abort();
227	    }
228	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
229	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
230	        std::abort();
231	    }
232	}
233	
234	void resetWriteBookkeeping() {
235	    g_haveSnapshot = false;
236	    g_progress = 0;
237	}
238	
239	// Outcome of one scripted write() call.
240	enum class WriteOutcome {
241	    kPass,       // behave as the real syscall with the given count
242	    kShort,      // behave as the real syscall but cap the count
243	    kEintr,      // report a recoverable interrupt, nothing written
244	    kEio,        // report an irrecoverable I/O error
245	    kZero,       // report zero bytes with data still pending
246	};
247	
248	struct ScriptedCall {
249	    WriteOutcome outcome;
250	    long limit;  // valid for kShort
251	};
252	
253	// Parse the next EF_TEST_WRITE_SCRIPT token. Returns false once the script is
254	// exhausted (the caller should then behave normally).
255	bool nextScriptedCall(ScriptedCall& call) {
256	    static char script[512];
257	    static bool initialized = false;
258	    static char* saveptr = nullptr;
259	
260	    if (!initialized) {
261	        const char* raw = std::getenv("EF_TEST_WRITE_SCRIPT");
262	        if (raw == nullptr) {
263	            script[0] = '\0';
264	        } else {
265	            std::strncpy(script, raw, sizeof(script) - 1);
266	            script[sizeof(script) - 1] = '\0';
267	        }
268	        saveptr = script;
269	        initialized = true;
270	    }
271	
272	    char* token = ::strtok_r(nullptr, ",", &saveptr);
273	    if (token == nullptr) {
274	        return false;
275	    }
276	    if (std::strcmp(token, "ok") == 0) {
277	        call.outcome = WriteOutcome::kPass;
278	    } else if (std::strcmp(token, "intr") == 0) {
279	        call.outcome = WriteOutcome::kEintr;
280	    } else if (std::strcmp(token, "eio") == 0) {
281	        call.outcome = WriteOutcome::kEio;
282	    } else if (std::strcmp(token, "zero") == 0) {
283	        call.outcome = WriteOutcome::kZero;
284	    } else {
285	        char* end = nullptr;
286	        long limit = std::strtol(token, &end, 10);
287	        if (end != token && *end == '\0' && limit > 0) {
288	            call.outcome = WriteOutcome::kShort;
289	            call.limit = limit;
290	        } else {
291	            // An unknown token is a test-script bug: fail loudly rather than
292	            // silently behave as a normal write.
293	            std::fprintf(stderr,
294	                         "envelopefile_testable: invalid write script token "
295	                         "'%s'\n", token);
296	            call.outcome = WriteOutcome::kEio;
297	        }
298	    }
299	    return true;
300	}
301	
302	}  // namespace
303	
304	int __wrap_open(const char* path, int flags, ...) {
305	    mode_t mode = 0;
306	    if ((flags & O_CREAT) != 0) {
307	        va_list args;
308	        va_start(args, flags);
309	        mode = static_cast<mode_t>(va_arg(args, int));
310	        va_end(args);
311	    }
312	    int fd = __real_open(path, flags, mode);
313	    if (fd != -1 && (flags & O_CREAT) != 0 && (flags & O_EXCL) != 0 &&
314	        isKeyPath(path)) {
315	        g_keyFd = fd;
316	        resetWriteBookkeeping();
317	    }
318	    return fd;
319	}
320	
321	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
322	    if (!isKeyFd(fd)) {
323	        return __real_write(fd, buffer, count);
324	    }
325	
326	    verifyIncomingBuffer(buffer, count);
327	
328	    const size_t requested = count;  // caller's original length for the log
329	    ScriptedCall call;
330	    const bool scripted = nextScriptedCall(call);
331	    if (scripted) {
332	        switch (call.outcome) {
333	            case WriteOutcome::kEintr:
334	                logCall(g_progress, requested, -1, EINTR);
335	                errno = EINTR;
336	                return -1;
337	            case WriteOutcome::kEio:
338	                logCall(g_progress, requested, -1, EIO);
339	                errno = EIO;
340	                return -1;
341	            case WriteOutcome::kZero:
342	                logCall(g_progress, requested, 0, 0);
343	                errno = 0;
344	                return 0;
345	            case WriteOutcome::kShort:
346	                if (count > static_cast<size_t>(call.limit)) {
347	                    count = static_cast<size_t>(call.limit);
348	                }
349	                break;
350	            case WriteOutcome::kPass:
351	                break;
352	        }
353	    } else {
354	        // Legacy single-knob injection, kept for the existing regressions.
355	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
356	            logCall(g_progress, requested, -1, EIO);
357	            errno = EIO;
358	            return -1;
359	        }
360	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
361	        if (chunk != nullptr) {
362	            const long limit = std::atol(chunk);
363	            if (limit > 0 && count > static_cast<size_t>(limit)) {
364	                count = static_cast<size_t>(limit);
365	            }
366	        }
367	    }
368	
369	    ssize_t result = __real_write(fd, buffer, count);
370	    logCall(g_progress, requested, result, errno);
371	    if (result > 0) {
372	        g_progress += static_cast<std::size_t>(result);
373	    }
374	    return result;
375	}
376	
377	int __wrap_fsync(int fd) {
378	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FSYNC")) {
379	        errno = EIO;
380	        return -1;
381	    }
382	    return __real_fsync(fd);
383	}
384	
385	int __wrap_close(int fd) {
386	    const bool wasKeyFd = isKeyFd(fd);
387	    const int result = __real_close(fd);
388	    if (wasKeyFd) {
389	        g_keyFd = -1;
390	        if (envFlagSet("EF_TEST_FAIL_CLOSE")) {
391	            // The descriptor is already closed for real; only the reported
392	            // status is faked, mirroring a genuine close(2) failure.
393	            errno = EIO;
394	            return -1;
395	        }
396	    }
397	    return result;
398	}
399	
400	int __wrap_RAND_bytes(unsigned char* buf, int num) {
401	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
402	        const int result = __real_RAND_bytes(buf, num);
403	        if (result == 1) {
404	            g_randBuf = buf;
405	            g_randBufSize = num;
406	            char line[96];
407	            std::snprintf(line, sizeof(line),
408	                          "RAND %d partial=0 result=ok", num);
409	            logKeyLine(line);
410	        }
411	        return result;
412	    }
413	
414	    g_randBuf = buf;
415	    g_randBufSize = num;
416	
417	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
418	    // not mistake the partial fill for a valid key.
419	    long partial = 0;
420	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
421	    if (raw != nullptr) {
422	        partial = std::atol(raw);
423	        if (partial < 0) {
424	            partial = 0;
425	        }
426	        if (partial > num) {
427	            partial = num;
428	        }
429	    }
430	    for (long i = 0; i < partial; ++i) {
431	        buf[i] = 0xA5;
432	    }
433	
434	    // Start from an empty error queue, then optionally leave a descriptive
435	    // OpenSSL error so the "detail" and "no detail" messages are both
436	    // exercised deterministically.
437	    ERR_clear_error();
438	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
439	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
440	        ERR_raise(ERR_LIB_RAND, 0x7f);
441	#else
442	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
443	#endif
444	    }
445	
446	    char line[96];
447	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
448	                  num, partial);
449	    logKeyLine(line);
450	    return 0;
451	}
452	
453	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
454	    if (ptr != nullptr && ptr == g_randBuf) {
455	        char line[96];
456	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
457	        logKeyLine(line);
458	        // The buffer is about to be released; do not match a stale address.
459	        g_randBuf = nullptr;
460	        g_randBufSize = 0;
461	    }
462	    __real_OPENSSL_cleanse(ptr, len);
463	}
464	
465	}  // extern "C"
